const body = $input.first().json;
const sender = body.data?.key?.remoteJid || '';
const phone = sender.replace('@s.whatsapp.net', '').replace('@g.us', '');
const messageType = body.data?.messageType || 'conversation';
const messageText = (body.data?.message?.conversation || body.data?.message?.extendedTextMessage?.text || '').trim().toLowerCase();
if (sender.includes('@g.us')) { return [{ json: { skip: true, phone, sender, response: '', isComplete: false, completedOrder: null, isBusinessHours: false } }]; }
const now = new Date();
const brtHour = (now.getUTCHours() - 3 + 24) % 24;
const brtDay = now.getUTCDay();
let isOpen = false;
if (brtDay >= 1 && brtDay <= 5 && brtHour >= 8 && brtHour < 18) isOpen = true;
if (brtDay === 6 && brtHour >= 8 && brtHour < 12) isOpen = true;
const CAFES = [{ name: 'Cafe Premium Suave', price: 69 }, { name: 'Cafe Especial Equilibrado', price: 69 }, { name: 'Cafe Gourmet Classico', price: 57 }, { name: 'Cafe Super Intenso', price: 57 }];
const staticData = $getWorkflowStaticData('global');
if (!staticData.conversations) staticData.conversations = {};
const conv = staticData.conversations[phone] || { state: 0, order: {} };
let state = conv.state;
let order = { ...conv.order };
let response = '';
let nextState = state;
let isComplete = false;
if (messageText === '1' && state !== 1) { state = 0; order = {}; }
if (state === 0) {
  response = 'Ola! Bem-vindo a Lounge Cafe!\n\nCardapio:\n1 - Cafe Premium Suave - R$ 69,00\n2 - Cafe Especial Equilibrado - R$ 69,00\n3 - Cafe Gourmet Classico - R$ 57,00\n4 - Cafe Super Intenso - R$ 57,00\n\nFarofa - R$ 30,00/unidade\n\nDigite o numero do cafe:';
  nextState = 1;
} else if (state === 1) {
  const choice = parseInt(messageText);
  if (choice >= 1 && choice <= 4) { order.cafe = CAFES[choice - 1]; response = order.cafe.name + ' selecionado!\nVoce prefere:\nG - Grao\nM - Moido\n\nDigite G ou M:'; nextState = 2; }
  else { response = 'Por favor, digite um numero de 1 a 4.'; nextState = 1; }
} else if (state === 2) {
  const t = messageText.charAt(0);
  if (t === 'g') { order.tipo = 'Grao'; }
  else if (t === 'm') { order.tipo = 'Moido'; }
  else { staticData.conversations[phone] = { state: 2, order }; return [{ json: { phone, sender, response: 'Digite G para Grao ou M para Moido:', isComplete: false, completedOrder: null, isBusinessHours: isOpen, skip: false } }]; }
  response = order.tipo + ' selecionado!\n\nQuantos pacotes de 500g voce deseja?'; nextState = 3;
} else if (state === 3) {
  const qty = parseInt(messageText);
  if (qty > 0 && qty <= 50) { order.quantidade = qty; response = qty + ' pacote(s) confirmado(s)!\n\nDeseja adicionar Farofa? (R$ 30,00/unidade)\nS - Sim\nN - Nao'; nextState = 4; }
  else { response = 'Informe uma quantidade valida (ex: 1, 2, 3...):'; nextState = 3; }
} else if (state === 4) {
  const t = messageText.charAt(0);
  if (t === 's') { order.farofa = 0; response = 'Quantas unidades de farofa deseja?'; nextState = 45; }
  else if (t === 'n') { order.farofa = 0; order.total = order.cafe.price * order.quantidade; order.produtos = order.cafe.name + ' (' + order.tipo + ') x' + order.quantidade; response = 'RESUMO DO PEDIDO\n\n' + order.produtos + '\nTotal: R$ ' + order.total + ',00\n\nQual e o seu nome completo?'; nextState = 5; }
  else { response = 'Digite S para Sim ou N para Nao:'; nextState = 4; }
} else if (state === 45) {
  const qty = parseInt(messageText);
  if (qty > 0 && qty <= 20) { order.farofa = qty; order.total = (order.cafe.price * order.quantidade) + (qty * 30); order.produtos = order.cafe.name + ' (' + order.tipo + ') x' + order.quantidade + ' + Farofa x' + qty; response = 'RESUMO DO PEDIDO\n\n' + order.produtos + '\nTotal: R$ ' + order.total + ',00\n\nQual e o seu nome completo?'; nextState = 5; }
  else { response = 'Informe uma quantidade valida:'; nextState = 45; }
} else if (state === 5) {
  order.nome = messageText.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  const fora = !isOpen ? '\n\nEstamos fora do horario comercial. Confirmaremos na abertura.' : '';
  response = 'Perfeito, ' + order.nome + '!\n\nPAGAMENTO VIA PIX\nChave: (19) 998972667\nBeneficiario: Ednea Cristina\nValor: R$ ' + order.total + ',00\n\nApos o PIX, envie o comprovante aqui para confirmarmos.' + fora; nextState = 6;
} else if (state === 6) {
  const isReceipt = ['imageMessage','documentMessage','image','document'].includes(messageType);
  if (isReceipt) { const confirmMsg = isOpen ? 'Em breve seu pedido estara pronto!' : 'Confirmaremos assim que abrirmos!'; response = 'Comprovante recebido!\n\n' + confirmMsg + '\n\nObrigado!\n\nDigite 1 para novo pedido.'; isComplete = true; nextState = 0; }
  else { response = 'Por favor, envie o comprovante do PIX (foto ou PDF).'; nextState = 6; }
} else { response = 'Nao entendi. Digite 1 para iniciar.'; }
const completedOrder = isComplete ? { ...conv.order, nome: order.nome } : null;
staticData.conversations[phone] = { state: isComplete ? 0 : nextState, order: isComplete ? {} : order };
return [{ json: { phone, sender, response, isComplete, completedOrder, isBusinessHours: isOpen, skip: false } }];

const botData = $('Process State Machine').first().json;
const order = botData.completedOrder || {};
const now = new Date();
const brt = new Date(now.getTime() - 3 * 60 * 60 * 1000);
const timestamp = brt.toLocaleString('pt-BR');
const isOpen = botData.isBusinessHours;
const fora = isOpen ? '' : ' FORA DO HORARIO';
return [{ json: { timestamp, nome: order.nome || '', phone: botData.phone, produtos: order.produtos || '', total: order.total || 0, pix: 'Comprovante recebido', status: 'Aguardando confirmacao', obs: fora, notifyMsg: 'Novo Pedido!' + fora + '\n\nCliente: ' + order.nome + '\nWhatsApp: ' + botData.phone + '\nPedido: ' + order.produtos + '\nTotal: R$ ' + order.total + ',00' }}];
